  if ( *a1 == 127 )
    return fwrite(ptr: "<undefined>\n", size: 1u, n: 0xCu, s);
  v4 = 0;
  fputc(c: 34, stream: s);
  do
  {
    while ( a1[v4] == 0 )
    {
      if ( ++v4 == 256 )
        return fwrite(ptr: "\"\n", size: 1u, n: 2u, s);
    }
    v5 = v4++;
    fputc(c: v5, stream: s);
  }
  while ( v4 != 256 );
  return fwrite(ptr: "\"\n", size: 1u, n: 2u, s);
}
